/**
 * Checks the repository and token with the Git host, then creates a webhook with a new
 * random secret. If OpsHub can't create it (token without admin/Maintainer access, the
 * host rejects the URL, or it is unreachable), the repository is connected in manual
 * mode and the response carries the payload URL and secret — shown only once.
 * Self-hosted hosts (`base_url`) that resolve to internal addresses are refused
 * (`SSRF_BLOCKED`) unless the operator allows them.
 * @summary Connect or replace the repository (repo.connect)
 */
export const connectRepository = async (projectId: string,
    connectRepositoryRequest: ConnectRepositoryRequest, options?: Parameters<typeof customFetch>[1]): Promise<ConnectRepositoryResult> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<ConnectRepositoryResult>(getConnectRepositoryUrl(projectId),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(connectRepositoryRequest)
  }
);}





